const DocumentFieldDetectionRequestSchema = z
  .object({
    file: z
      .file()
      .exactOptional()
      .openapi({
        type: 'string',
        format: 'binary',
        description:
          'The PDF file to analyze.\n\nThis endpoint requires either `file` or `file_url`, but not both.',
      }),
    file_url: z
      .url()
      .exactOptional()
      .openapi({
        description:
          'The URL of the PDF file to analyze.\n\nThis endpoint requires either `file` or `file_url`, but not both.',
      }),
    detection_mode: z
      .xor([
        z
          .string()
          .regex(/^annotations$/)
          .openapi({ example: 'annotations' }),
        z
          .string()
          .regex(/^text_tags$/)
          .openapi({ example: 'text_tags' }),
      ])
      .openapi({
        description:
          'The field detection method to use. Set to `annotations` to detect PDF form annotations or `text_tags` to detect Dropbox Sign text tags.',
      }),
    page_range: z
      .string()
      .regex(/^(?:all|\d+(?:-\d+)?(?:,\d+(?:-\d+)?)*)$/)
      .exactOptional()
      .openapi({
        description:
          'The zero-based page indexes to analyze. Accepts `all`, individual pages, inclusive ranges, or comma-separated combinations, such as `0-2,5,7-9`. Defaults to `all`.',
        example: '0-2,5,7-9',
      }),
  })
  .openapi({ required: ['detection_mode'] })
  .openapi('DocumentFieldDetectionRequest')

