const DocumentFieldDetectionResponseDetectionResultSchema = z
  .object({
    document_hash: z
      .string()
      .length(64)
      .openapi({ description: 'The SHA-256 hash of the analyzed document.' }),
    detection_mode: z
      .xor([
        z
          .string()
          .regex(/^annotations$/)
          .openapi({ example: 'annotations' }),
        z
          .string()
          .regex(/^text_tags$/)
          .openapi({ example: 'text_tags' }),
      ])
      .openapi({
        description:
          'The field detection method used to analyze the document: `annotations` or `text_tags`.',
      }),
    page_count: z
      .int()
      .min(0)
      .openapi({ description: 'The total number of pages in the document.' }),
    pages_analyzed: z
      .string()
      .openapi({
        description:
          'The zero-based page indexes analyzed, represented by the requested `page_range`, or `all` when every page was analyzed.',
        example: 'all',
      }),
    detected_at: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The Unix timestamp when the field detection result was generated.',
      }),
    form_fields_per_document: z
      .array(SubFormFieldsPerDocumentBaseSchema)
      .openapi({
        description:
          'The fields that should appear on the document, expressed as an array of objects. (For more details you can read about it here: [Using Form Fields per Document](/docs/openapi/form-fields-per-document).)\n\n**NOTE:** Fields like **text**, **dropdown**, **checkbox**, **radio**, and **hyperlink** have additional required and optional parameters. Check out the list of [additional parameters](/api/reference/constants/#form-fields-per-document) for these field types.\n\n* Text Field use `SubFormFieldsPerDocumentText`\n* Dropdown Field use `SubFormFieldsPerDocumentDropdown`\n* Hyperlink Field use `SubFormFieldsPerDocumentHyperlink`\n* Checkbox Field use `SubFormFieldsPerDocumentCheckbox`\n* Radio Field use `SubFormFieldsPerDocumentRadio`\n* Signature Field use `SubFormFieldsPerDocumentSignature`\n* Date Signed Field use `SubFormFieldsPerDocumentDateSigned`\n* Initials Field use `SubFormFieldsPerDocumentInitials`\n* Text Merge Field use `SubFormFieldsPerDocumentTextMerge`\n* Checkbox Merge Field use `SubFormFieldsPerDocumentCheckboxMerge`',
      }),
    form_field_groups: z
      .array(SubFormFieldGroupSchema)
      .openapi({
        description:
          'Group information for fields defined in `form_fields_per_document`. String-indexed JSON array with `group_label` and `requirement` keys. `form_fields_per_document` must contain fields referencing a group defined in `form_field_groups`.',
      }),
    warnings: z
      .array(WarningResponseSchema)
      .openapi({ description: 'Non-fatal issues encountered during field detection.' }),
    errors: z
      .array(ErrorResponseErrorSchema)
      .openapi({
        description:
          'Errors encountered during field detection. Successfully detected fields may still be included in the response.',
      }),
    suggestions: z
      .array(z.string())
      .openapi({ description: 'Suggestions for improving the field detection results.' }),
  })
  .openapi({
    required: [
      'document_hash',
      'detection_mode',
      'page_count',
      'pages_analyzed',
      'detected_at',
      'form_fields_per_document',
      'form_field_groups',
      'warnings',
      'errors',
      'suggestions',
    ],
    'x-internal-class': true,
  })
  .openapi('DocumentFieldDetectionResponseDetectionResult')

