export const postApiAppRoute = createRoute({
  method: 'post',
  path: '/api_app',
  tags: ['Api App'],
  summary: 'Create API App',
  description: 'Creates a new API App.',
  operationId: 'apiAppCreate',
  request: {
    body: {
      content: {
        'application/json': {
          schema: ApiAppCreateRequestSchema,
          examples: { example: ApiAppCreateRequestExample },
        },
        'multipart/form-data': {
          schema: z
            .object({
              callback_url: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'The URL at which the ApiApp should receive event callbacks.',
                }),
              custom_logo_file: z
                .file()
                .exactOptional()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description:
                    'An image file to use as a custom logo in embedded contexts. (Only applies to some API plans)',
                }),
              domains: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string()).min(1).max(10),
                )
                .openapi({ description: 'The domain names the ApiApp will be associated with.' }),
              name: z
                .string()
                .openapi({ description: 'The name you want to assign to the ApiApp.' }),
              oauth: SubOAuthSchema.exactOptional(),
              options: z
                .object({
                  can_insert_everywhere: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .default(false)
                    .exactOptional()
                    .openapi({
                      description:
                        'Determines if signers can use "Insert Everywhere" when signing a document.',
                    }),
                })
                .exactOptional()
                .openapi({ description: 'Additional options supported by API App.', required: [] }),
              white_labeling_options: z
                .object({
                  header_background_color: z.string().default('#1a1a1a').exactOptional(),
                  legal_version: z.enum(['terms1', 'terms2']).default('terms1').exactOptional(),
                  link_color: z.string().default('#0061FE').exactOptional(),
                  page_background_color: z.string().default('#f7f8f9').exactOptional(),
                  primary_button_color: z.string().default('#0061FE').exactOptional(),
                  primary_button_color_hover: z.string().default('#0061FE').exactOptional(),
                  primary_button_text_color: z.string().default('#ffffff').exactOptional(),
                  primary_button_text_color_hover: z.string().default('#ffffff').exactOptional(),
                  secondary_button_color: z.string().default('#ffffff').exactOptional(),
                  secondary_button_color_hover: z.string().default('#ffffff').exactOptional(),
                  secondary_button_text_color: z.string().default('#0061FE').exactOptional(),
                  secondary_button_text_color_hover: z.string().default('#0061FE').exactOptional(),
                  text_color1: z.string().default('#808080').exactOptional(),
                  text_color2: z.string().default('#ffffff').exactOptional(),
                  reset_to_default: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        'Resets white labeling options to defaults. Only useful when updating an API App.',
                    }),
                })
                .exactOptional()
                .openapi({
                  description:
                    "An array of elements and values serialized to a string, to be used to customize the app's signer page. (Only applies to some API plans)\n\nTake a look at our [white labeling guide](https://developers.hellosign.com/api/reference/premium-branding/) to learn more.",
                  required: [],
                }),
            })
            .openapi({ required: ['name', 'domains'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'successful operation',
      content: {
        'application/json': {
          schema: ApiAppGetResponseSchema,
          examples: { example: ApiAppCreateResponseExample },
        },
      },
      headers: z.object({
        'X-RateLimit-Limit': XRateLimitLimitHeaderSchema,
        'X-RateLimit-Remaining': XRateLimitRemainingHeaderSchema,
        'X-Ratelimit-Reset': XRatelimitResetHeaderSchema,
      }),
    },
    '4XX': {
      description: 'failed_operation',
      content: {
        'application/json': {
          schema: ErrorResponseSchema,
          examples: {
            '400_example': Error400ResponseExample,
            '401_example': Error401ResponseExample,
            '402_example': Error402ResponseExample,
            '403_example': Error403ResponseExample,
            '429_example': Error429ResponseExample,
            '404_example': Error404ResponseExample,
            '4XX_example': Error4XXResponseExample,
          },
        },
      },
    },
  },
  security: [{ api_key: [] }, { oauth2: ['api_app_access'] }],
})

