export const getFaxListRoute = createRoute({
  method: 'get',
  path: '/fax/list',
  tags: ['Fax'],
  summary: 'Lists Faxes',
  description: 'Returns properties of multiple Faxes',
  operationId: 'faxList',
  request: {
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            description: 'Which page number of the Fax List to return. Defaults to `1`.',
            schema: { type: 'integer', default: 1, minimum: 1 },
            example: 1,
            required: false,
          },
        }),
      page_size: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'page_size',
            in: 'query',
            description:
              'Number of objects to be returned per page. Must be between `1` and `100`. Default is `20`.',
            schema: { type: 'integer', default: 20, maximum: 100, minimum: 1 },
            example: 20,
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'successful operation',
      content: {
        'application/json': {
          schema: FaxListResponseSchema,
          examples: { example: FaxListResponseExample },
        },
      },
      headers: z.object({
        'X-RateLimit-Limit': XRateLimitLimitHeaderSchema,
        'X-RateLimit-Remaining': XRateLimitRemainingHeaderSchema,
        'X-Ratelimit-Reset': XRatelimitResetHeaderSchema,
      }),
    },
    '4XX': {
      description: 'failed_operation',
      content: {
        'application/json': {
          schema: ErrorResponseSchema,
          examples: {
            '400_example': Error400ResponseExample,
            '401_example': Error401ResponseExample,
            '402_example': Error402ResponseExample,
            '403_example': Error403ResponseExample,
            '429_example': Error429ResponseExample,
            '4XX_example': Error4XXResponseExample,
          },
        },
      },
    },
  },
  security: [{ api_key: [] }],
})

export const postFaxSendRoute = createRoute({
  method: 'post',
  path: '/fax/send',
  tags: ['Fax'],
  summary: 'Send Fax',
  description: 'Creates and sends a new Fax with the submitted file(s)',
  operationId: 'faxSend',
  request: {
    body: {
      content: {
        'application/json': {
          schema: FaxSendRequestSchema,
          examples: { example: FaxSendRequestExample },
        },
        'multipart/form-data': {
          schema: z
            .object({
              recipient: z
                .string()
                .openapi({
                  description:
                    'Recipient of the fax \nCan be a phone number in E.164 format or email address',
                  example: 'recipient@example.com',
                }),
              sender: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Fax Send From Sender (used only with fax number)',
                  example: 'sender@example.com',
                }),
              files: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.file().openapi({ type: 'string', format: 'binary' })),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Use `files[]` to indicate the uploaded file(s) to fax\n\nThis endpoint requires either **files** or **file_urls[]**, but not both.',
                }),
              file_urls: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string()),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Use `file_urls[]` to have Dropbox Fax download the file(s) to fax\n\nThis endpoint requires either **files** or **file_urls[]**, but not both.',
                }),
              test_mode: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({ description: 'API Test Mode Setting' }),
              cover_page_to: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Fax cover page recipient information',
                  example: 'Recipient Name',
                }),
              cover_page_from: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Fax cover page sender information',
                  example: 'Sender Name',
                }),
              cover_page_message: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Fax Cover Page Message',
                  example: 'Please find the attached documents.',
                }),
              title: z
                .string()
                .exactOptional()
                .openapi({ description: 'Fax Title', example: 'Fax Title' }),
            })
            .openapi({ required: ['recipient'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'successful operation',
      content: {
        'application/json': {
          schema: FaxGetResponseSchema,
          examples: { example: FaxGetResponseExample },
        },
      },
      headers: z.object({
        'X-RateLimit-Limit': XRateLimitLimitHeaderSchema,
        'X-RateLimit-Remaining': XRateLimitRemainingHeaderSchema,
        'X-Ratelimit-Reset': XRatelimitResetHeaderSchema,
      }),
    },
    '4XX': {
      description: 'failed_operation',
      content: {
        'application/json': {
          schema: ErrorResponseSchema,
          examples: {
            '400_example': Error400ResponseExample,
            '401_example': Error401ResponseExample,
            '402_example': Error402ResponseExample,
            '403_example': Error403ResponseExample,
            '429_example': Error429ResponseExample,
            '404_example': Error404ResponseExample,
            '4XX_example': Error4XXResponseExample,
          },
        },
      },
    },
  },
  security: [{ api_key: [] }],
})

